import json, csv
import pandas as pd

FIELD_MAP = {
    'user_id': 'user_id', 'id': 'user_id', 'userId': 'user_id',
    'email': 'email', 'email_address': 'email',
    'full_name': 'name', 'name': 'name', 'userName': 'name',
    'registration_date': 'created_date', 'created_at': 'created_date', 'joined': 'created_date',
}
UNIFIED = ['user_id', 'name', 'email', 'created_date']


def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    try:
        return pd.to_datetime(v).strftime('%Y-%m-%d')
    except Exception:
        return str(v)


def status_of(rec):
    if 'status' in rec and rec['status'] not in (None, ''):
        return str(rec['status'])
    for k in ('is_active', 'active'):
        if k in rec and rec[k] is not None:
            v = rec[k]
            if isinstance(v, str):
                v = v.strip().lower() in ('true', '1', 'yes', 'active')
            return 'active' if bool(v) else 'inactive'
    return None


def normalize(raw):
    out = {}
    for k, v in raw.items():
        if k in FIELD_MAP:
            uk = FIELD_MAP[k]
            if isinstance(v, float) and pd.isna(v):
                v = None
            if uk == 'created_date':
                v = norm_date(v)
            elif uk == 'user_id' and v is not None:
                v = int(v)
            elif v is not None:
                v = str(v)
            out[uk] = v
    out['status'] = status_of(raw)
    return out


# read sources
with open('/data/source_a/users.json') as f:
    src_a = [normalize(r) for r in json.load(f)]

src_b = []
with open('/data/source_b/users.csv') as f:
    for r in csv.DictReader(f):
        src_b.append(normalize(r))

df_c = pd.read_parquet('/data/source_c/users.parquet')
src_c = [normalize(r) for r in df_c.to_dict('records')]

sources = {'source_a': src_a, 'source_b': src_b, 'source_c': src_c}
PRIORITY = ['source_a', 'source_b', 'source_c']

# index by user_id
by_user = {}
for sname in PRIORITY:
    for rec in sources[sname]:
        uid = rec.get('user_id')
        if uid is None:
            continue
        by_user.setdefault(uid, {})[sname] = rec

merged = []
conflicts = []
for uid in sorted(by_user):
    present = by_user[uid]
    ordered = [s for s in PRIORITY if s in present]
    out = {'user_id': int(uid)}
    for field in ['name', 'email', 'created_date', 'status']:
        vals = {}
        for s in ordered:
            v = present[s].get(field)
            if v is not None:
                vals[s] = v
        selected = None
        for s in ordered:
            v = present[s].get(field)
            if v is not None:
                selected = v
                break
        out[field] = selected
        if field in UNIFIED and len(set(vals.values())) > 1:
            conflicts.append({
                'user_id': int(uid),
                'field': field,
                'values': vals,
                'selected': selected,
            })
    merged.append(out)

mdf = pd.DataFrame(merged, columns=['user_id', 'name', 'email', 'created_date', 'status'])
mdf['user_id'] = mdf['user_id'].astype('int64')
for c in ['name', 'email', 'created_date', 'status']:
    mdf[c] = mdf[c].astype('object')
mdf.to_parquet('/app/merged_users.parquet', index=False)

report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print(mdf)
print(json.dumps(report, indent=2))

